    extern __shared__ float sdata[];

    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    // Load data into shared memory, handling out-of-bounds
    if (idx < n) {
        sdata[tid] = in[idx];
