double mlp_loss_and_grad(const double* params, int n_in, int n_hidden,
                         const double* X, const double* y, int n_samples,
                         double* grad) {
    // Layout of params:
    // W1: n_hidden * n_in
    // b1: n_hidden
    // W2: n_hidden
    // b2: 1

    // Offsets
    int W1_off = 0;
    int b1_off = W1_off + n_hidden * n_in;
    int W2_off = b1_off + n_hidden;
    int b2_off = W2_off + n_hidden;

    // Initialize grad to zero
    int total_params = n_hidden * n_in + n_hidden + n_hidden + 1;
    for (int i = 0; i < total_params; ++i) {
        grad[i] = 0.0;
    }

    double total_loss = 0.0;

    // Loop over samples
    for (int s = 0; s < n_samples; ++s) {
        const double* x = X + s * n_in;
        double y_s = y[s];

        // Forward pass
        // h_j = tanh(sum_k W1[j][k] * x[k] + b1[j])
        // We need h and also the pre-activation for gradient computation

        // Allocate temporary arrays on stack (small network assumed)
        // But since we can't use dynamic allocation easily without new, and n_hidden/n_in are small,
        // we can use fixed size or just compute on the fly.
        // Let's use local arrays. Max size assumption? The problem says "small neural network".
        // To be safe with stack, let's assume reasonable sizes. If not, we'd need malloc.
        // Given constraints, let's use VLA-like approach or just fixed max if needed.
        // Actually, standard C++ doesn't support VLAs. Let's use a reasonable max or dynamic.
        // Since we can't include <vector> or <new>, and only <cmath>, we might need to be careful.
        // However, typically in such problems, stack allocation with reasonable limits is acceptable,
        // or we can compute gradients without storing all h's if we do two passes? 
        // No, we need h for backprop.
        // Let's assume n_hidden and n_in are small enough for stack.
        // If not, we'd need to use malloc/free which requires <cstdlib>. The prompt says "no library beyond <cmath>".
        // This implies we should avoid dynamic allocation or assume stack is sufficient.
        // Let's use a fixed max size for safety, e.g., 1024.

        const int MAX_DIM = 1024;
        double h[MAX_DIM];
        double pre_h[MAX_DIM]; // pre-activation of hidden layer

        // Compute hidden layer
        for (int j = 0; j < n_hidden; ++j) {
            double sum = 0.0;
            for (int k = 0; k < n_in; ++k) {
                sum += params[W1_off + j * n_in + k] * x[k];
            }
            sum += params[b1_off + j];
            pre_h[j] = sum;
            h[j] = std::tanh(sum);
        }

        // Compute output
        double z = 0.0;
        for (int j = 0; j < n_hidden; ++j) {
            z += params[W2_off + j] * h[j];
        }
        z += params[b2_off];

        double p = 1.0 / (1.0 + std::exp(-z));

        // Loss
        // loss = -(y*log(p) + (1-y)*log(1-p))
        // Handle edge cases for log(0)
        double eps = 1e-15;
        double p_clamped = p;
        if (p_clamped < eps) p_clamped = eps;
        if (p_clamped > 1.0 - eps) p_clamped = 1.0 - eps;

        double loss_s = -(y_s * std::log(p_clamped) + (1.0 - y_s) * std::log(1.0 - p_clamped));
        total_loss += loss_s;

        // Backpropagation
        // dL/dz = p - y
        double dz = p - y_s;

        // Gradients for W2 and b2
        // dL/dW2[j] = dz * h[j]
        // dL/db2 = dz
        for (int j = 0; j < n_hidden; ++j) {
            grad[W2_off + j] += dz * h[j];
        }
        grad[b2_off] += dz;

        // Gradients for hidden layer
        // dL/dh[j] = dz * W2[j]
        // dL/dpre_h[j] = dL/dh[j] * (1 - h[j]^2)  [derivative of tanh]
        // dL/dW1[j][k] = dL/dpre_h[j] * x[k]
        // dL/db1[j] = dL/dpre_h[j]

        for (int j = 0; j < n_hidden; ++j) {
            double dh = dz * params[W2_off + j];
            double dpre_h = dh * (1.0 - h[j] * h[j]);

            grad[b1_off + j] += dpre_h;

            for (int k = 0; k < n_in; ++k) {
                grad[W1_off + j * n_in + k] += dpre_h * x[k];
            }
        }
    }

    // Average loss and gradients
    double inv_n = 1.0 / n_samples;
    for (int i = 0; i < total_params; ++i) {
        grad[i] *= inv_n;
    }

    return total_loss * inv_n;
}
