struct Tape {
    struct Node {
        double value;
        double grad;
        int op; // 0: constant/input, 1: add, 2: mul, 3: sin, 4: exp
        int a;  // left operand id
        int b;  // right operand id
    };

    std::vector<Node> nodes;

    int constant(double v) {
        nodes.push_back({v, 0.0, 0, -1, -1});
        return (int)nodes.size() - 1;
    }

    int input(double v) {
        nodes.push_back({v, 0.0, 0, -1, -1});
        return (int)nodes.size() - 1;
    }

    int add(int a, int b) {
        double val = nodes[a].value + nodes[b].value;
        nodes.push_back({val, 0.0, 1, a, b});
        return (int)nodes.size() - 1;
    }

    int mul(int a, int b) {
        double val = nodes[a].value * nodes[b].value;
        nodes.push_back({val, 0.0, 2, a, b});
        return (int)nodes.size() - 1;
    }

    int sin_(int a) {
        double val = std::sin(nodes[a].value);
        nodes.push_back({val, 0.0, 3, a, -1});
        return (int)nodes.size() - 1;
    }

    int exp_(int a) {
        double val = std::exp(nodes[a].value);
        nodes.push_back({val, 0.0, 4, a, -1});
        return (int)nodes.size() - 1;
    }

    double value(int node) const {
        return nodes[node].value;
    }

    void backward(int root) {
        // Reset gradients
        for (auto& n : nodes) {
            n.grad = 0.0;
        }
        nodes[root].grad = 1.0;

        // Reverse sweep: from root down to 0
        // Since nodes are created in topological order (parents after children),
        // iterating backwards ensures consumers are processed before inputs.
        for (int i = root; i >= 0; --i) {
            double g = nodes[i].grad;
            if (g == 0.0) continue;

            switch (nodes[i].op) {
                case 1: { // add
                    int a = nodes[i].a;
                    int b = nodes[i].b;
                    nodes[a].grad += g;
                    nodes[b].grad += g;
                    break;
                }
                case 2: { // mul
                    int a = nodes[i].a;
                    int b = nodes[i].b;
                    nodes[a].grad += g * nodes[b].value;
                    nodes[b].grad += g * nodes[a].value;
                    break;
                }
                case 3: { // sin
                    int a = nodes[i].a;
                    nodes[a].grad += g * std::cos(nodes[a].value);
                    break;
                }
                case 4: { // exp
                    int a = nodes[i].a;
                    nodes[a].grad += g * nodes[i].value; // exp(x) is value
                    break;
                }
                default:
                    break;
            }
        }
    }

    double grad(int node) const {
        return nodes[node].grad;
    }
};
