  reg [PTR_WIDTH_PLUS_1-1:0] rptr_bin;
  reg [PTR_WIDTH_PLUS_1-1:0] rptr_gray;
  reg [PTR_WIDTH_PLUS_1-1:0] rptr_gray_sync; // Synchronized write pointer in read domain

  // Synchronizers
  reg [PTR_WIDTH_PLUS_1-1:0] wptr_gray_sync_1, wptr_gray_sync_2;
  reg [PTR_WIDTH_PLUS_1-1:0] rptr_gray_sync_1, rptr_gray_sync_2;

  // Binary to Gray conversion function
  function [PTR_WIDTH_PLUS_1-1:0] bin2gray;
    input [PTR_WIDTH_PLUS_1-1:0] bin;
    begin
      bin2gray = bin ^ (bin >> 1);
    end
  endfunction

  // Write Domain Logic
  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wptr_bin <= 0;
      wptr_gray <= 0;
    end else begin
      if (winc && !wfull) begin
        wptr_bin <= wptr_bin + 1;
        wptr_gray <= bin2gray(wptr_bin + 1);
      end
    end
