    if (winc && !wfull) begin
      mem[wptr_bin[PTR_WIDTH-1:0]] <= wdata;
    end
  end

  // Synchronize Read Pointer to Write Domain
  always @(posedge wclk or negedge wrst_n) begin
    if (!wrst_n) begin
      wptr_gray_sync_1 <= 0;
      wptr_gray_sync_2 <= 0;
    end else begin
